-- Чернетки, створені з візуалізацій. Перевірте адресу, площі, ціну та
-- конструктивні рішення перед зміною published на true.
insert into public.properties (
  id, slug, title, description, price, currency, property_type, transaction_type,
  status, city, address, area, land_area, bedrooms, bathrooms, rooms, floors,
  year_built, distance_to_lutsk_km, featured, published, highlights, attributes
)
values
  ('10000000-0000-4000-8000-000000000001', 'budynok-strumivka-112', 'Будинок у Струмівці', 'Одноповерховий будинок площею 112 м². У чернетці вказано керамоблок 250 мм, утеплення фасаду 150 мм, монолітний фундамент і покрівлю з металочерепиці. Перед публікацією підтвердьте комплектацію та комунікації.', 80000, 'USD', 'house', 'sale', 'available', 'Струмівка', 'Струмівка, Луцький район', 112, 6, 3, 2, 4, 1, 2026, 7, false, false, array['Керамоблок 250 мм — підтвердити','Утеплення фасаду 150 мм — підтвердити','Монолітний фундамент — підтвердити','Ділянка 6 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000002', 'budynok-rovyantsi-118', 'Будинок у Рованцях', 'Компактний одноповерховий будинок площею 118 м² з великою кухнею-вітальнею. Заявлена конструкція: керамічний блок, фасадне утеплення 150 мм та енергоощадні вікна. Дані є чернеткою для перевірки.', 83000, 'USD', 'house', 'sale', 'available', 'Рованці', 'Рованці, Луцький район', 118, 6, 3, 2, 4, 1, 2026, 4, false, false, array['Керамічний блок — підтвердити','Енергоощадні вікна — підтвердити','Ділянка 6 соток — уточнити','Планування на 4 кімнати'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000003', 'budynok-bogoliuby-124', 'Будинок у Боголюбах', 'Одноповерховий будинок 124 м² із терасою та приватним подвір’ям. У підготовленій специфікації: керамоблок 250 мм, мінераловатне утеплення 150 мм і утеплена стеля. Усі технічні параметри мають бути підтверджені до публікації.', 86000, 'USD', 'house', 'sale', 'available', 'Боголюби', 'Боголюби, Луцький район', 124, 7, 3, 2, 4, 1, 2026, 9, false, false, array['Керамоблок 250 мм — підтвердити','Мінеральна вата 150 мм — підтвердити','Тераса — уточнити площу','Ділянка 7 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000004', 'budynok-prylutske-138', 'Будинок у Прилуцькому', 'Будинок 138 м² з гаражем і функціональним плануванням. Чернетка містить заявлені матеріали: керамічний блок, фасадне утеплення 150 мм, монолітне перекриття в зоні гаража. Потребує перевірки перед оприлюдненням.', 99000, 'USD', 'house', 'sale', 'available', 'Прилуцьке', 'Прилуцьке, Луцький район', 138, 7, 3, 2, 5, 1, 2026, 8, false, false, array['Гараж — уточнити площу','Керамоблок — підтвердити','Утеплення 150 мм — підтвердити','Ділянка 7 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000005', 'budynok-knyagynynok-126', 'Будинок у Княгининку', 'Одноповерховий будинок 126 м² із критою терасою. Заявлена комплектація: керамоблок 250 мм, утеплення фасаду 150 мм, покрівля з металочерепиці та енергоощадні склопакети. Чернетка: підтвердіть дані перед публікацією.', 92000, 'USD', 'house', 'sale', 'available', 'Княгининок', 'Княгининок, Луцький район', 126, 6, 3, 2, 4, 1, 2026, 11, false, false, array['Крита тераса — уточнити','Керамоблок 250 мм — підтвердити','Склопакети — підтвердити','Ділянка 6 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000006', 'budynok-lypyny-116', 'Будинок у Липинах', 'Будинок площею 116 м² з навісом для авто та облаштованим двором. Заявлено: керамоблок, зовнішнє утеплення 150 мм, відмостка й водовідведення. Це чернетка для подальшого підтвердження характеристик.', 88000, 'USD', 'house', 'sale', 'available', 'Липини', 'Липини, Луцький район', 116, 5, 3, 2, 4, 1, 2026, 3, false, false, array['Навіс для авто — уточнити','Керамоблок — підтвердити','Утеплення 150 мм — підтвердити','Водовідведення — підтвердити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000007', 'budynok-zaborol-104', 'Будинок у Заборолі', 'Компактний дуплекс: секція 104 м² з окремим входом і подвір’ям. Передбачені керамічний блок, утеплення фасаду 150 мм та окремі лічильники. Публікуйте лише після підтвердження планування й правового статусу.', 80000, 'USD', 'house', 'sale', 'available', 'Забороль', 'Забороль, Луцький район', 104, 3, 2, 2, 3, 1, 2026, 8, false, false, array['Секція дуплексу — підтвердити','Окремі комунікації — підтвердити','Керамоблок — підтвердити','Ділянка 3 сотки — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000008', 'budynok-hirka-polonka-110', 'Будинок у Гіркій Полонці', 'Одноповерховий будинок 110 м² з просторою вітальнею. У чернетці закладено керамоблок 250 мм, утеплення фасаду 150 мм та покрівлю з металочерепиці. Уточніть усі характеристики перед публікацією.', 85000, 'USD', 'house', 'sale', 'available', 'Гірка Полонка', 'Гірка Полонка, Луцький район', 110, 6, 3, 2, 4, 1, 2026, 5, false, false, array['Керамоблок 250 мм — підтвердити','Утеплення фасаду 150 мм — підтвердити','Покрівля — підтвердити','Ділянка 6 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb),
  ('10000000-0000-4000-8000-000000000009', 'budynok-borokhiv-120', 'Будинок у Борохові', 'Одноповерховий будинок 120 м² із навісом для авто та терасою. Заявлені керамічний блок, утеплення 150 мм і енергоощадні вікна. Картка збережена як чернетка — перевірте всі дані до оприлюднення.', 94000, 'USD', 'house', 'sale', 'available', 'Борохів', 'Борохів, Луцький район', 120, 7, 3, 2, 4, 1, 2026, 14, false, false, array['Навіс для авто — уточнити','Керамічний блок — підтвердити','Енергоощадні вікна — підтвердити','Ділянка 7 соток — уточнити'], '{"source":"visualization","requires_verification":true}'::jsonb)
on conflict (slug) do update set
  title = excluded.title, description = excluded.description, price = excluded.price,
  city = excluded.city, address = excluded.address, area = excluded.area,
  land_area = excluded.land_area, bedrooms = excluded.bedrooms, bathrooms = excluded.bathrooms,
  rooms = excluded.rooms, floors = excluded.floors, year_built = excluded.year_built,
  distance_to_lutsk_km = excluded.distance_to_lutsk_km, highlights = excluded.highlights,
  attributes = excluded.attributes, published = false, updated_at = now();

